NEW_661 = "6.6.1. Если для подготовки Детализированного отчета, проверки конкретного начисления либо ответа на запрос Лицензиара требуется получение дополнительных сведений от Агрегатора, Сервиса, банка или иного третьего лица, срок предоставления соответствующей информации исчисляется с момента фактического получения Лицензиатом сведений, достаточных для ее подготовки и проверки. Лицензиат уведомляет Лицензиара о направлении такого запроса либо необходимости дополнительной проверки. Само по себе ожидание ответа третьего лица не рассматривается как отказ от предоставления информации или признание отсутствия соответствующего начисления."
NEW_617 = "6.17. Неполнота Исходных данных, отсутствие отдельных Релизов, Объектов, строк, Сервисов, территорий, периодов, UPC/ISRC либо иных идентификаторов в информации, фактически полученной Лицензиатом от Агрегатора или Сервиса, само по себе не означает отсутствие соответствующего использования, отказ Лицензиата от его учета либо отсутствие у Лицензиара права на вознаграждение при его фактическом наличии. После получения недостающих Исходных данных либо достоверного установления их принадлежности соответствующему Релизу Лицензиат отражает такие данные посредством Технической корректировки и, при необходимости, производит перерасчет Баланса."
RENAMED_618 = "6.18. Неполучение Лицензиаром уведомления вследствие неактуальности указанных им контактных данных, непроверки ЛКПО либо иных обстоятельств, находящихся на стороне Лицензиара, не влияет на момент предоставления Отчета."


def set_paragraph_text(paragraph, value):
    paragraph.clear()
    paragraph.add_run(value)


document = Document(SOURCE)
paragraphs = document.paragraphs
insert_after = None
insert_617_after = None

if any(paragraph.text.strip().startswith("6.18.") for paragraph in paragraphs):
    raise RuntimeError("Section 6.18 already exists")

for paragraph in paragraphs:
    text = paragraph.text.strip()
    if text.startswith("6.17."):
        set_paragraph_text(paragraph, RENAMED_618)
        continue
    if text.startswith("6.6."):
        insert_after = paragraph
        continue
    if text.startswith("6.16."):
        insert_617_after = paragraph
        continue
    for prefix, replacement in REPLACEMENTS.items():
        if prefix == "6.17.":
            continue
        if text.startswith(prefix):
            set_paragraph_text(paragraph, replacement)
            if prefix == "6.6.":
                insert_after = paragraph
            break

if insert_after is None or insert_617_after is None:
    raise RuntimeError("Required insertion point was not found")

new_paragraph = deepcopy(insert_after._p)
insert_after._p.addnext(new_paragraph)
new_paragraph = Paragraph(new_paragraph, insert_after._parent)
set_paragraph_text(new_paragraph, NEW_661)

new_paragraph = deepcopy(insert_617_after._p)
insert_617_after._p.addnext(new_paragraph)
new_paragraph = Paragraph(new_paragraph, insert_617_after._parent)
set_paragraph_text(new_paragraph, NEW_617)

# The source document contains an empty page-break paragraph after the
# requisites table, producing a blank page before Appendix 1.
for paragraph in document.paragraphs:
    if not paragraph.text.strip() and 'w:type="page"' in paragraph._p.xml:
        paragraph._element.getparent().remove(paragraph._element)

OUTPUT.parent.mkdir(parents=True, exist_ok=True)
document.save(OUTPUT)
